    (* keep = "true" *) reg [7:0] bank_client_g_s1; always @(posedge clk) bank_client_g_s1 <= bank_client_g_s0;
    (* keep = "true" *) reg [7:0] bank_client_g_s2; always @(posedge clk) bank_client_g_s2 <= bank_client_g_s1;
    wire [7:0] bank_client_c = bank_client_g_s2;
    (* keep = "true" *) reg [1:0] hub_ring_enable_g_s0; always @(posedge clk) hub_ring_enable_g_s0 <= hub_ring_enable;
    (* keep = "true" *) reg [1:0] hub_ring_enable_g_s1; always @(posedge clk) hub_ring_enable_g_s1 <= hub_ring_enable_g_s0;
    (* keep = "true" *) reg [1:0] hub_ring_enable_g_s2; always @(posedge clk) hub_ring_enable_g_s2 <= hub_ring_enable_g_s1;
    wire [1:0] hub_ring_enable_c = hub_ring_enable_g_s2;
    (* keep = "true" *) reg [1:0] hub_ring_client_g_s0; always @(posedge clk) hub_ring_client_g_s0 <= hub_ring_client;
    (* keep = "true" *) reg [1:0] hub_ring_client_g_s1; always @(posedge clk) hub_ring_client_g_s1 <= hub_ring_client_g_s0;
    (* keep = "true" *) reg [1:0] hub_ring_client_g_s2; always @(posedge clk) hub_ring_client_g_s2 <= hub_ring_client_g_s1;
    wire [1:0] hub_ring_client_c = hub_ring_client_g_s2;
    (* keep = "true" *) reg replay_enable_g_s0; always @(posedge clk) replay_enable_g_s0 <= replay_enable;
    (* keep = "true" *) reg replay_enable_g_s1; always @(posedge clk) replay_enable_g_s1 <= replay_enable_g_s0;
    (* keep = "true" *) reg replay_enable_g_s2; always @(posedge clk) replay_enable_g_s2 <= replay_enable_g_s1;
    wire replay_enable_c = replay_enable_g_s2;
    (* keep = "true" *) reg replay_source_g_s0; always @(posedge clk) replay_source_g_s0 <= replay_source;
    (* keep = "true" *) reg replay_source_g_s1; always @(posedge clk) replay_source_g_s1 <= replay_source_g_s0;
    (* keep = "true" *) reg replay_source_g_s2; always @(posedge clk) replay_source_g_s2 <= replay_source_g_s1;
    wire replay_source_c = replay_source_g_s2;
    wire [2:0] hub_status_c;
    (* keep = "true" *) reg [2:0] hub_status_g_s0; always @(posedge clk) hub_status_g_s0 <= hub_status_c;
    (* keep = "true" *) reg [2:0] hub_status_g_s1; always @(posedge clk) hub_status_g_s1 <= hub_status_g_s0;
    (* keep = "true" *) reg [2:0] hub_status_g_s2; always @(posedge clk) hub_status_g_s2 <= hub_status_g_s1;
    assign hub_status = hub_status_g_s2;
    wire [18:0] vmstat_c;
    (* keep = "true" *) reg [18:0] vmstat_g_s0; always @(posedge clk) vmstat_g_s0 <= vmstat_c;
    (* keep = "true" *) reg [18:0] vmstat_g_s1; always @(posedge clk) vmstat_g_s1 <= vmstat_g_s0;
    (* keep = "true" *) reg [18:0] vmstat_g_s2; always @(posedge clk) vmstat_g_s2 <= vmstat_g_s1;
    assign vmstat = vmstat_g_s2;
    // NW: the wq2-merge leaves (vmm_NWb) sticky flt -> bank status bit 17 (as hfd_hgi_vms_static_NW_glue)
    wire [143:0] bank_status_m;
    assign bank_status_m[17:0] = {bank_status_c[17] | bk_flt_c[0], bank_status_c[16:0]};
    assign bank_status_m[35:18] = {bank_status_c[35] | bk_flt_c[1], bank_status_c[34:18]};
    assign bank_status_m[53:36] = {bank_status_c[53] | bk_flt_c[2], bank_status_c[52:36]};
    assign bank_status_m[71:54] = {bank_status_c[71] | bk_flt_c[3], bank_status_c[70:54]};
    assign bank_status_m[89:72] = {bank_status_c[89] | bk_flt_c[4], bank_status_c[88:72]};
    assign bank_status_m[107:90] = {bank_status_c[107] | bk_flt_c[5], bank_status_c[106:90]};
    assign bank_status_m[125:108] = {bank_status_c[125] | bk_flt_c[6], bank_status_c[124:108]};
    assign bank_status_m[143:126] = {bank_status_c[143] | bk_flt_c[7], bank_status_c[142:126]};
    wire [(NC+1)*338-1:0] hcq;
    wire [(NC+1)*274-1:0] hcr;
    wire [337:0] hq;
    wire [273:0] hr=hcr[NC*274+:274];
    assign hcq=hq;
    wire [289:0] pi0_h,pi1_h;
    wire [265:0] ri0_h,ri1_h;
    wire rfault2;
    // seam relays (the core_lt g4 relays): pi / ri leave from these flops, cco / rce / stop faults land on them
    reg [289:0] pi0_r,pi1_r; reg [265:0] ri0_r,ri1_r; reg [263:0] cco0_r,cco1_r; reg [287:0] rce0_r,rce1_r; reg [2:0] rf_r;
    always @(posedge clk) begin
        pi0_r<=pi0_h; pi1_r<=pi1_h; ri0_r<=ri0_h; ri1_r<=ri1_h; cco0_r<=cco0; cco1_r<=cco1; rce0_r<=rce0; rce1_r<=rce1;
        rf_r<={rfault2,fault1,fault0};
    end
    assign pi0=(RMUT == 5 || MUT == 9) ? pi0_h : pi0_r;
    assign pi1=(RMUT == 5) ? pi1_h : pi1_r;
    assign ri0=ri0_r; assign ri1=ri1_r;
    wire [287:0] rce0_s=(RMUT == 5 || MUT == 9) ? rce0 : rce0_r, rce1_s=(RMUT == 5) ? rce1 : rce1_r;
    wire [2:0] hub_status_w;
    assign hub_status_c=hub_status_w;
    ot_vms_hub_lt #(.NC(NC),.CW(CW),.MUT(RMUT),.NLH(NLH)) u_hub(
        .clk(clk),.rl(rl[0+:NLH]),.sid(2'd2),.cq(hcq),.cr(hcr),
        .client_seq(client_seq_c),.response_enable(response_enable_c),.response_seq(response_seq_c),
        .bank_enable(bank_enable_c),.bank_client(bank_client_c),
        .cw_enable(hub_ring_enable_c[0]),.cw_client(hub_ring_client_c[0+:CW]),
        .ccw_enable(hub_ring_enable_c[1]),.ccw_client(hub_ring_client_c[CW+:CW]),
        .pq(bk_pq_c),.pr(bk_pr_c),.cwi(pi0_h),.cci(pi1_h),.cco0(cco0_r),.cco1(cco1_r),.status(hub_status_w));
    ot_vms_rcl_lt u_replay(.clk(clk),.rl(rl[NLH+:3]),.sid(2'd2),
        .rx_enable(replay_enable_c),.rx_source(replay_source_c),.rce0(rce0_s),.rce1(rce1_s),
        .hq(hq),.hr(hr),.ri0(ri0_h),.ri1(ri1_h),.fault(rfault2));
    ot_vms_status_static u_status(.clk(clk),.rst_n(rl[NLH+3]),
        .bank_status(bank_status_m),.hub_status(hub_status_w),.ring_fault(|rf_r),.vmstat(vmstat_c));
    (* keep = "true" *) reg ring_fault_g_s0; always @(posedge clk) ring_fault_g_s0 <= rfault2;
    (* keep = "true" *) reg ring_fault_g_s1; always @(posedge clk) ring_fault_g_s1 <= ring_fault_g_s0;
    (* keep = "true" *) reg ring_fault_g_s2; always @(posedge clk) ring_fault_g_s2 <= ring_fault_g_s1;
    assign ring_fault = ring_fault_g_s2;
endmodule

